const BG = ['zoneA', 'zoneB', 'zoneC'] as const;
// gallery (opens with HOOK) + the extra dynamic types + widgets (drop its HOOK).
const raw = [...gallery.scenes, ...extra, ...widgets.scenes.slice(1)];
const scenes: Scene[] = raw.map((s, i) => ({
  ...s,
  id: `sc${String(i + 1).padStart(2, '0')}`,
  transition: TRANSITIONS[i % TRANSITIONS.length],
  background: s.background ?? BG[i % 3],
}));

export const showcaseSpec: VideoSpec = {
  meta: {topic: 'Component showcase — every scene type in this design', format: 'long', fps: 30, onePayoff: 'x', topicAxes: ['a', 'b']},
  brand: {theme: 'studio'},
  scenes,
};

// AUTHORITATIVE showcase scene index — the SINGLE SOURCE OF TRUTH for the matrix
// tooling (scripts/dump-showcase.mjs emits it to audit/showcase-scenes.json, which
// scripts/matrix-shots.mjs consumes). Derived from the SAME `scenes` array the
// composition renders, so still labels and frame offsets can NEVER drift. coverFrames
// is 0 for the showcase (no `cover`), so startFrame == the real composition frame.
// NEVER regex-parse this file's text to rebuild this — import this export.
const variantOf = (s: Scene): string | undefined => {
  const d = s.data as Record<string, unknown> | undefined;
  if (!d) return undefined;
  const g = (k: string, f: string): string | undefined => {
    const o = d[k] as Record<string, unknown> | undefined;
    return o && typeof o[f] === 'string' ? (o[f] as string) : undefined;
  };
  switch (s.type) {
    case 'PIPELINE': return g('pipeline', 'variant');
    case 'CODE_EDITOR': return g('editor', 'variant');
    case 'WINDOW_FRAME': return g('window', 'variant');
    case 'DIAGRAM': return g('diagram', 'variant');
    case 'LAYERED_STACK': return g('stack', 'variant');
    case 'PACKET': return g('packet', 'variant');
    case 'K8S_CLUSTER': return g('k8s', 'mode');
    case 'BITS': return g('bits', 'variant');
    case 'CACHE_PYRAMID': return g('pyramid', 'variant');
    case 'STATE_MACHINE': return g('stateMachine', 'variant');
    case 'ENCRYPTION': return g('encryption', 'mode');
    case 'CONFIDENCE_GATE': return g('confidence', 'mode');
    case 'CALL_STACK': return g('callStack', 'mode');
    default: return undefined;
  }
};

export interface ShowcaseSceneMeta {
  index: number;
  id: string;
  type: string;
  variant?: string;
  durationFrames: number;
  startFrame: number;
  midFrame: number;
}

export const showcaseScenes: ShowcaseSceneMeta[] = (() => {
  let off = 0;
  return scenes.map((s, i) => {
    const startFrame = off;
    off += s.durationFrames;
    return {
      index: i,
      id: s.id,
      type: s.type,
      variant: variantOf(s),
      durationFrames: s.durationFrames,
      startFrame,
      midFrame: startFrame + Math.floor(s.durationFrames * 0.55),
    };
  });
})();

